sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float contrast;
uniform float toe;
uniform float shoulder;
uniform float fade;
uniform float saturation;
uniform float warmth;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 sat3(float3 c, float s) {
    return mix(float3(dot(c, float3(0.2126, 0.7152, 0.0722))), c, s);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 t = saturate((s - 0.5) * contrast + 0.5);
    float3 lo = pow(t, float3(1.0 + toe));
    float3 hi = 1.0 - pow(1.0 - t, float3(1.0 + shoulder));
    float3 o = mix(lo, hi, t);
    o = o * (1.0 - fade) + fade;
    o = sat3(o, saturation);
    o *= float3(1.0 + warmth * 0.12, 1.0, 1.0 - warmth * 0.12);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
